var t=`1124-clam-chowder`;var n=`world-1124`;var a=`US`;var s=`northern-america`;var o=4;var r=40;var l={en:`Clam Chowder`,ua:`Клем-чаудер`};var h={en:`Clam Chowder is a dish from United States prepared with bacon, yellow onion, celery stalk, all-purpose flour. This is a home-scale version with measured ingredients in the individual steps where they are used. Fish stock replaces fresh clam liquor in the base; add clam cooking juices if available.`,ua:`Клем-чаудер, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: бекон, жовта цибуля, стебло селери, пшеничне борошно універсальне. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Рибний бульйон замінює свіжий сік молюсків у основі; за можливості додайте рідину від їх приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`bacon`,180,`g`],[`yellow-onion`,200,`g`],[`celery-stalk`,160,`g`],[`unsalted-butter`,55,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 7 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 7 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:7,i:[[`all-purpose-flour`,55,`g`],[`whole-cow-milk`,300,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`potato`,370,`g`],[`clam`,800,`g`],[`fish-stock`,520,`ml`],[`thyme`,4,`sprig`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`heavy-cream`,220,`ml`],[`parsley`,20,`g`]]}];var u={slug:t,id:n,country:`US`,region:s,servings:4,minutes:40,title:l,text:h,steps:d};export{a as country,u as default,n as id,r as minutes,s as region,o as servings,t as slug,d as steps,h as text,l as title};